export type ParsedTallyOrTriggerRunoffInstruction<
  TProgram extends string = typeof PACTUM_DISPUTES_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    dispute: TAccountMetas[0];
    disputeConfig: TAccountMetas[1];
    marketplace: TAccountMetas[2];
    client: TAccountMetas[3];
    provider: TAccountMetas[4];
    agreement?: TAccountMetas[5] | undefined;
    reservation?: TAccountMetas[6] | undefined;
    escrowVault: TAccountMetas[7];
    clientTokenAccount: TAccountMetas[8];
    providerTokenAccount: TAccountMetas[9];
    platformVault: TAccountMetas[10];
    feeDestination: TAccountMetas[11];
    judgeStakeVault: TAccountMetas[12];
    usdcMint: TAccountMetas[13];
    rentPayer: TAccountMetas[14];
    escrowConfig: TAccountMetas[15];
    treasuryConfig: TAccountMetas[16];
    globalConfig: TAccountMetas[17];
    cpiAuthority: TAccountMetas[18];
    escrowCpiAuthority: TAccountMetas[19];
    treasuryCpiAuthority: TAccountMetas[20];
    escrowProgram: TAccountMetas[21];
    treasuryProgram: TAccountMetas[22];
    coreProgram: TAccountMetas[23];
    tokenProgram: TAccountMetas[24];
  };
  data: TallyOrTriggerRunoffInstructionData;
};

export function parseTallyOrTriggerRunoffInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedTallyOrTriggerRunoffInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 25) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 25,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount();
    return accountMeta.address === PACTUM_DISPUTES_PROGRAM_ADDRESS
      ? undefined
      : accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      dispute: getNextAccount(),
      disputeConfig: getNextAccount(),
      marketplace: getNextAccount(),
      client: getNextAccount(),
      provider: getNextAccount(),
      agreement: getNextOptionalAccount(),
      reservation: getNextOptionalAccount(),
      escrowVault: getNextAccount(),
      clientTokenAccount: getNextAccount(),
      providerTokenAccount: getNextAccount(),
      platformVault: getNextAccount(),
      feeDestination: getNextAccount(),
      judgeStakeVault: getNextAccount(),
      usdcMint: getNextAccount(),
      rentPayer: getNextAccount(),
      escrowConfig: getNextAccount(),
      treasuryConfig: getNextAccount(),
      globalConfig: getNextAccount(),
      cpiAuthority: getNextAccount(),
      escrowCpiAuthority: getNextAccount(),
      treasuryCpiAuthority: getNextAccount(),
      escrowProgram: getNextAccount(),
      treasuryProgram: getNextAccount(),
      coreProgram: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getTallyOrTriggerRunoffInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
